export function personalDeliveryState(config){
  const plan=scope.NM_DELIVERY_PLAN.fromConfig(config);
  if(!plan)return 'invalid';
  const at=scope.NM_DELIVERY_PLAN.assignment(scope.NM_COURSES,plan,config.week,config.deliveryPlanVersion);
  if(!at||!Array.isArray(at.weekLessons))return 'invalid';
  return at.weekLessons.length?'scheduled':'empty';
}
